contracts/production/StakingWalletCosmic.content:
// #region

// SPDX-License-Identifier: CC0-1.0
pragma solidity =0.8.34;

// #endregion
// #region

import { ReentrancyGuardTransient } from "@openzeppelin/contracts/utils/ReentrancyGuardTransient.sol";
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";
import { CosmicSignatureErrors } from "./libraries/CosmicSignatureErrors.sol";
import { CosmicSignatureEvents } from "./libraries/CosmicSignatureEvents.sol";
import { CosmicSignatureNft } from "./CosmicSignatureNft.sol";
import { IStakingWalletNftBase, StakingWalletNftBase } from "./StakingWalletNftBase.sol";
import { IStakingWalletCosmicSignatureNft } from "./interfaces/IStakingWalletCosmicSignatureNft.sol";

// #endregion
// #region

contract StakingWalletCosmicSignatureNft is ReentrancyGuardTransient, Ownable, StakingWalletNftBase, IStakingWalletCosmicSignatureNft {
	// #region Data Types

	/// @notice Stores details about an NFT stake action.
	struct StakeAction {
		uint256 nftId;

		/// @dev
		/// [Comment-202504011]
		/// Would it make sense to reorder variables like `nftOwnerAddress` and `stakerAddress` to before `NftId`?
		/// Regardless, let's leave it alone.
		/// [/Comment-202504011]
		address nftOwnerAddress;

		/// @notice A copy of `StakingWalletCosmicSignatureNft.rewardAmountPerStakedNft`
		/// saved when creating this `StakeAction` instance.
		uint256 initialRewardAmountPerStakedNft;
	}

	// #endregion
	// #region State

	/// @notice The `CosmicSignatureNft` contract address.
	CosmicSignatureNft public immutable nft;

	/// @notice The `CosmicSignatureGame` contract address.
	address public immutable game;

	/// @notice Details about currently staked NFTs.
	/// Item index corresponds to stake action ID.
	/// Comment-202502266 relates.
	/// This array is sparse (can contain gaps).
	StakeAction[1 << 64] public stakeActions;

	/// @notice The all-time cumulative staking ETH reward amount per staked NFT.
	uint256 public rewardAmountPerStakedNft = 0;

	// #endregion
	// #region `constructor`

	/// @notice Constructor.
	/// @param nft_ The `CosmicSignatureNft` contract address.
	/// @param game_ The `CosmicSignatureGame` contract address.
	/// @dev
	/// Observable universe entities accessed here:
	///    Inherited `constructor`s.
	///    `_msgSender`.
	///    `_providedAddressIsNonZero`.
	///    `nft`.
	///    `game`.
	constructor(CosmicSignatureNft nft_, address game_)
		_providedAddressIsNonZero(address(nft_))
		_providedAddressIsNonZero(game_)
		Ownable(_msgSender()) {
		nft = nft_;
		game = game_;
	}

	// #endregion
	// #region `_onlyGame`

	/// @dev Comment-202411253 applies.
	modifier _onlyGame() {
		_checkOnlyGame();
		_;
	}

	// #endregion
	// #region `_checkOnlyGame`

	/// @dev Comment-202411253 applies.
	function _checkOnlyGame() private view {
		if (_msgSender() != game) {
			revert CosmicSignatureErrors.UnauthorizedCaller("Only the CosmicSignatureGame contract is permitted to call this method.", _msgSender());
		}
	}

	// #endregion
	// #region `stake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `nonReentrant`.
	///    `_stake`.
	function stake(uint256 nftId_) external override (IStakingWalletNftBase, StakingWalletNftBase) nonReentrant {
		_stake(nftId_);
	}

	// #endregion
	// #region `_stake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `_msgSender`.
	///    `numStakedNfts`.
	///    `actionCounter`.
	///    `super._stake`.
	///    `NftStaked`.
	///    `StakeAction`.
	///    `nft`.
	///    `stakeActions`.
	///    `rewardAmountPerStakedNft`.
	function _stake(uint256 nftId_) internal override {
		super._stake(nftId_);
		uint256 newActionCounter_ = actionCounter + 1;
		actionCounter = newActionCounter_;
		uint256 newStakeActionId_ = newActionCounter_;
		StakeAction storage newStakeActionReference_ = stakeActions[newStakeActionId_];
		// #enable_asserts assert(newStakeActionReference_.nftId == 0);
		newStakeActionReference_.nftId = nftId_;
		// #enable_asserts assert(newStakeActionReference_.nftOwnerAddress == address(0));
		newStakeActionReference_.nftOwnerAddress = _msgSender();
		uint256 rewardAmountPerStakedNftCopy_ = rewardAmountPerStakedNft;
		// #enable_asserts assert(newStakeActionReference_.initialRewardAmountPerStakedNft == 0);
		newStakeActionReference_.initialRewardAmountPerStakedNft = rewardAmountPerStakedNftCopy_;
		uint256 newNumStakedNfts_ = numStakedNfts + 1;
		numStakedNfts = newNumStakedNfts_;
		emit NftStaked(newStakeActionId_, nftId_, _msgSender(), newNumStakedNfts_, rewardAmountPerStakedNftCopy_);

		// Comment-202501145 applies.
		nft.transferFrom(_msgSender(), address(this), nftId_);
	}

	// #endregion
	// #region `stakeMany`

	/// @dev
	/// Observable universe entities accessed here:
	///    `nonReentrant`.
	///    `_stakeMany`.
	function stakeMany(uint256[] calldata nftIds_) external override (IStakingWalletNftBase, StakingWalletNftBase) nonReentrant {
		_stakeMany(nftIds_);
	}

	// #endregion
	// #region `unstake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `nonReentrant`.
	///    `_unstake`.
	///    `_payReward`.
	function unstake(uint256 stakeActionId_) external override nonReentrant {
		// This can potentially be zero.
		uint256 rewardAmount_ = _unstake(stakeActionId_);

		_payReward(rewardAmount_);
	}

	// #endregion
	// #region `unstakeMany`

	/// @dev
	/// Observable universe entities accessed here:
	///    `nonReentrant`.
	///    `_unstake`.
	///    `_payReward`.
	function unstakeMany(uint256[] calldata stakeActionIds_) external override nonReentrant {
		uint256 rewardAmountsSum_ = 0;
		for (uint256 stakeActionIdIndex_ = stakeActionIds_.length; stakeActionIdIndex_ > 0; ) {
			-- stakeActionIdIndex_;

			// This can potentially be zero.
			uint256 rewardAmount_ = _unstake(stakeActionIds_[stakeActionIdIndex_]);

			rewardAmountsSum_ += rewardAmount_;
		}
		_payReward(rewardAmountsSum_);
	}

	// #endregion
	// #region `_unstake`

	/// @notice Makes state updates needed to unstake an NFT.
	/// @return The staking ETH reward amount.
	/// It can potentially be zero.
	/// The caller is required to pay it to the staker.
	/// @dev
	/// Observable universe entities accessed here:
	///    `CosmicSignatureErrors.NftStakeActionInvalidId`.
	///    `CosmicSignatureErrors.NftStakeActionAccessDenied`.
	///    `_msgSender`.
	///    `numStakedNfts`.
	///    `actionCounter`.
	///    `NftUnstaked`.
	///    `StakeAction`.
	///    `nft`.
	///    `stakeActions`.
	///    `rewardAmountPerStakedNft`.
	function _unstake(uint256 stakeActionId_) private returns (uint256) {
		StakeAction storage stakeActionReference_ = stakeActions[stakeActionId_];
		StakeAction memory stakeActionCopy_ = stakeActionReference_;
		if (_msgSender() != stakeActionCopy_.nftOwnerAddress) {
			if (stakeActionCopy_.nftOwnerAddress == address(0)) {
				revert CosmicSignatureErrors.NftStakeActionInvalidId("Invalid NFT stake action ID.", stakeActionId_);
			} else {
				revert CosmicSignatureErrors.NftStakeActionAccessDenied("Only NFT owner is permitted to unstake it.", stakeActionId_, _msgSender());
			}
		}
		delete stakeActionReference_.nftId;
		delete stakeActionReference_.nftOwnerAddress;
		delete stakeActionReference_.initialRewardAmountPerStakedNft;
		uint256 rewardAmountPerStakedNftCopy_ = rewardAmountPerStakedNft;

		// This can potentially be zero.
		uint256 rewardAmount_ = rewardAmountPerStakedNftCopy_ - stakeActionCopy_.initialRewardAmountPerStakedNft;

		uint256 newNumStakedNfts_ = numStakedNfts - 1;
		numStakedNfts = newNumStakedNfts_;
		uint256 newActionCounter_ = actionCounter + 1;
		actionCounter = newActionCounter_;
		emit NftUnstaked(newActionCounter_, stakeActionId_, stakeActionCopy_.nftId, _msgSender(), newNumStakedNfts_, rewardAmountPerStakedNftCopy_, rewardAmount_);

		// Comment-202501145 applies.
		nft.transferFrom(address(this), _msgSender(), stakeActionCopy_.nftId);

		return rewardAmount_;
	}

	// #endregion
	// #region `_payReward`

	/// @notice This stupid method just transfers the given ETH amount to whoever calls it.
	/// @param rewardAmount_ The ETH amount to transfer.
	/// It's OK if it's zero.
	/// @dev
	/// Observable universe entities accessed here:
	///    `address.call`.
	///    `CosmicSignatureErrors.FundTransferFailed`.
	///    `_msgSender`.
	function _payReward(uint256 rewardAmount_) private {
		// Comment-202502043 applies.
		(bool isSuccess_, ) = _msgSender().call{value: rewardAmount_}("");

		if ( ! isSuccess_ ) {
			revert CosmicSignatureErrors.FundTransferFailed("NFT staking ETH reward payment failed.", _msgSender(), rewardAmount_);
		}
	}

	// #endregion
	// #region `deposit`

	/// @dev
	/// Observable universe entities accessed here:
	///    `msg.value`.
	///    `nonReentrant`.
	///    `numStakedNfts`.
	///    `actionCounter`.
	///    `EthDepositReceived`.
	///    `rewardAmountPerStakedNft`.
	///    `_onlyGame`.
	function deposit(uint256 roundNum_) external payable override nonReentrant _onlyGame {
		uint256 numStakedNftsCopy_ = numStakedNfts;

		// [Comment-202410161]
		// The division can panic due to division by zero.
		// This quotient can potentially be zero.
		// Comment-202503043 relates and/or applies.
		// [/Comment-202410161]
		// Comment-202412045 applies.
		uint256 rewardAmountPerStakedNftIncrement_ = msg.value / numStakedNftsCopy_;

		uint256 newRewardAmountPerStakedNft_ = rewardAmountPerStakedNft + rewardAmountPerStakedNftIncrement_;
		rewardAmountPerStakedNft = newRewardAmountPerStakedNft_;
		uint256 newActionCounter_ = actionCounter + 1;
		actionCounter = newActionCounter_;
		emit EthDepositReceived(roundNum_, newActionCounter_, msg.value, newRewardAmountPerStakedNft_, numStakedNftsCopy_);
	}

	// #endregion
	// #region `tryPerformMaintenance`

	/// @dev
	/// Observable universe entities accessed here:
	///    `address.balance`.
	///    `address.call`.
	///    `nonReentrant`.
	///    `CosmicSignatureErrors.ThereAreStakedNfts`.
	///    `CosmicSignatureEvents.FundsTransferredToCharity`.
	///    `CosmicSignatureEvents.FundTransferFailed`.
	///    `numStakedNfts`.
	///    `onlyOwner`.
	/// I have made this method `nonReentrant`. Although that could be unnecessary if we assumed
	/// that the owner is not malicious. But at least this is helpful to silence Certora.
	function tryPerformMaintenance(address charityAddress_) external override nonReentrant onlyOwner returns (bool) {
		// #region

		require(numStakedNfts == 0, CosmicSignatureErrors.ThereAreStakedNfts("There are still staked NFTs."));

		// #endregion
		// #region

		bool returnValue_ = true;

		// #endregion
		// #region

		if (charityAddress_ != address(0)) {
			// It's OK if this is zero.
			uint256 amount_ = address(this).balance;

			// [Comment-202507296]
			// This would revert if `charityAddress_ == address(this)`.
			// [/Comment-202507296]
			// Comment-202502043 applies.
			(bool isSuccess_, ) = charityAddress_.call{value: amount_}("");

			if (isSuccess_) {
				emit CosmicSignatureEvents.FundsTransferredToCharity(charityAddress_, amount_);
			} else {
				emit CosmicSignatureEvents.FundTransferFailed("ETH transfer to charity failed.", charityAddress_, amount_);
				returnValue_ = false;
			}
		}

		// #endregion
		// #region

		return returnValue_;

		// #endregion
	}

	// #endregion
}

// #endregion

contracts/production/StakingWalletNftBas.content:
// #region

// SPDX-License-Identifier: CC0-1.0
pragma solidity =0.8.34;

// #endregion
// #region

import { CosmicSignatureErrors } from "./libraries/CosmicSignatureErrors.sol";
import { AddressValidator } from "./AddressValidator.sol";
import { IStakingWalletNftBase } from "./interfaces/IStakingWalletNftBase.sol";

// #endregion
// #region

abstract contract StakingWalletNftBase is AddressValidator, IStakingWalletNftBase {
	// #region State

	/// @notice The current staked NFT count.
	/// [Comment-202502266]
	/// This is the number of populated `stakeActions` items.
	/// `stakeActionIds` contains the same number of populated items.
	/// [/Comment-202502266]
	uint256 public numStakedNfts = 0;

	/// @notice Each Random Walk or Cosmic Signature NFT is allowed to be used for staking only once.
	/// If an item of this array at a particular index is a nonzero it means the NFT with that ID has already been used for staking.
	/// It doesn't specify whether the given NFT is still staked or has already been unstaked.
	/// See also: `CosmicSignatureGameStorage.usedRandomWalkNfts`.
	uint256[1 << 64] public usedNfts;

	/// @notice This variable is used to generate monotonic unique IDs.
	/// @dev One might want to declare this variable `internal` (and name it `_...`), but Nick needs it to be `public`.
	uint256 public actionCounter = 0;

	// #endregion
	// #region `constructor`

	/// @notice Constructor.
	/// @dev
	/// Observable universe entities accessed here:
	///    Inherited `constructor`s.
	constructor() {
		// Doing nothing.
	}

	// #endregion
	// #region `stake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `_stake`.
	function stake(uint256 nftId_) external override virtual {
		_stake(nftId_);
	}

	// #endregion
	// #region `_stake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `CosmicSignatureErrors.NftHasAlreadyBeenStaked`.
	///    `usedNfts`.
	function _stake(uint256 nftId_) internal virtual {
		require(
			usedNfts[nftId_] == 0,
			CosmicSignatureErrors.NftHasAlreadyBeenStaked("This NFT has already been staked in the past. An NFT is allowed to be staked only once.", nftId_)
		);
		usedNfts[nftId_] = 1;
	}

	// #endregion
	// #region `stakeMany`

	/// @dev
	/// Observable universe entities accessed here:
	///    `_stakeMany`.
	function stakeMany(uint256[] calldata nftIds_) external override virtual {
		_stakeMany(nftIds_);
	}

	// #endregion
	// #region `_stakeMany`

	/// @dev
	/// Observable universe entities accessed here:
	///    `_stake`.
	function _stakeMany(uint256[] calldata nftIds_) internal {
		for (uint256 nftIdIndex_ = nftIds_.length; nftIdIndex_ > 0; ) {
			-- nftIdIndex_;
			_stake(nftIds_[nftIdIndex_]);
		}
	}

	// #endregion
}

// #endregion

contracts/production/StakingWalletRandom.content:
// #region

// SPDX-License-Identifier: CC0-1.0
pragma solidity =0.8.34;

// #endregion
// #region

import { CosmicSignatureErrors } from "./libraries/CosmicSignatureErrors.sol";
import { RandomNumberHelpers } from "./libraries/RandomNumberHelpers.sol";
import { RandomWalkNFT } from "./RandomWalkNFT.sol";
import { StakingWalletNftBase } from "./StakingWalletNftBase.sol";
import { IStakingWalletRandomWalkNft } from "./interfaces/IStakingWalletRandomWalkNft.sol";

// #endregion
// #region

contract StakingWalletRandomWalkNft is StakingWalletNftBase, IStakingWalletRandomWalkNft {
	// #region Data Types

	/// @notice Stores details about an NFT stake action.
	struct StakeAction {
		uint256 nftId;

		/// @dev Comment-202504011 applies.
		address nftOwnerAddress;

		/// @notice
		/// [Comment-202502271]
		/// Index of this `StakeAction` instance in `StakingWalletRandomWalkNft.stakeActionIds`.
		/// [/Comment-202502271]
		/// @dev It can change zero or more times over the `StakeAction` instance lifetime.
		uint256 index;
	}

	// #endregion
	// #region State

	/// @notice The `RandomWalkNFT` contract address.
	RandomWalkNFT public immutable randomWalkNft;

	/// @notice Details about currently staked NFTs.
	/// Item index corresponds to stake action ID.
	/// Comment-202502266 relates.
	/// Unlike `stakeActionIds`, this array is sparse (can contain gaps).
	StakeAction[1 << 64] public stakeActions;

	/// @notice An item contains a stake action ID.
	/// Comment-202502271 relates.
	/// Comment-202502266 relates.
	/// Unlike `stakeActions`, this array is not sparse (contains no gaps).
	/// [Comment-202502261]
	/// This array can contain undeleted garbage beyond `numStakedNfts` items.
	/// [/Comment-202502261]
	uint256[1 << 64] public stakeActionIds;

	// #endregion
	// #region `constructor`

	/// @notice Constructor.
	/// @param randomWalkNft_ The `RandomWalkNFT` contract address.
	/// @dev
	/// Observable universe entities accessed here:
	///    Inherited `constructor`s.
	///    `_providedAddressIsNonZero`.
	///    `randomWalkNft`.
	constructor(RandomWalkNFT randomWalkNft_) _providedAddressIsNonZero(address(randomWalkNft_)) {
		randomWalkNft = randomWalkNft_;
	}

	// #endregion
	// #region `_stake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `msg.sender`.
	///    `numStakedNfts`.
	///    `actionCounter`.
	///    `super._stake`.
	///    `NftStaked`.
	///    `StakeAction`.
	///    `randomWalkNft`.
	///    `stakeActions`.
	///    `stakeActionIds`.
	function _stake(uint256 nftId_) internal override {
		super._stake(nftId_);
		uint256 newActionCounter_ = actionCounter + 1;
		actionCounter = newActionCounter_;
		uint256 newStakeActionId_ = newActionCounter_;
		StakeAction storage newStakeActionReference_ = stakeActions[newStakeActionId_];
		// #enable_asserts assert(newStakeActionReference_.nftId == 0);
		newStakeActionReference_.nftId = nftId_;
		// #enable_asserts assert(newStakeActionReference_.nftOwnerAddress == address(0));
		newStakeActionReference_.nftOwnerAddress = msg.sender;
		uint256 newNumStakedNfts_ = numStakedNfts;
		uint256 newStakeActionIndex_ = newNumStakedNfts_;
		// #enable_asserts assert(newStakeActionReference_.index == 0);
		newStakeActionReference_.index = newStakeActionIndex_;

		// It's possible that this item is already populated because we didn't delete it near Comment-202502263.
		// We are now overwriting it.
		stakeActionIds[newStakeActionIndex_] = newStakeActionId_;

		++ newNumStakedNfts_;
		numStakedNfts = newNumStakedNfts_;
		emit NftStaked(newStakeActionId_, nftId_, msg.sender, newNumStakedNfts_);

		// [Comment-202501145]
		// Somewhere around here or in the caller method
		// it could make sense to use the feature Comment-202501144 is talking about.
		// [/Comment-202501145]
		randomWalkNft.transferFrom(msg.sender, address(this), nftId_);
	}

	// #endregion
	// #region `unstake`

	/// @dev
	/// Observable universe entities accessed here:
	///    `msg.sender`.
	///    `CosmicSignatureErrors.NftStakeActionInvalidId`.
	///    `CosmicSignatureErrors.NftStakeActionAccessDenied`.
	///    `numStakedNfts`.
	///    `actionCounter`.
	///    `NftUnstaked`.
	///    `StakeAction`.
	///    `randomWalkNft`.
	///    `stakeActions`.
	///    `stakeActionIds`.
	function unstake(uint256 stakeActionId_) public override {
		// #region

		StakeAction storage stakeActionReference_ = stakeActions[stakeActionId_];
		StakeAction memory stakeActionCopy_ = stakeActionReference_;

		// #endregion
		// #region

		if (msg.sender != stakeActionCopy_.nftOwnerAddress) {
			if (stakeActionCopy_.nftOwnerAddress == address(0)) {
				revert CosmicSignatureErrors.NftStakeActionInvalidId("Invalid NFT stake action ID.", stakeActionId_);
			} else {
				// #enable_asserts assert(stakeActionIds[stakeActions[stakeActionId_].index] == stakeActionId_);
				revert CosmicSignatureErrors.NftStakeActionAccessDenied("Only NFT owner is permitted to unstake it.", stakeActionId_, msg.sender);
			}
		}
		// #enable_asserts assert(stakeActionIds[stakeActions[stakeActionId_].index] == stakeActionId_);

		// #endregion
		// #region

		delete stakeActionReference_.nftId;
		delete stakeActionReference_.nftOwnerAddress;
		uint256 newNumStakedNfts_ = numStakedNfts - 1;
		numStakedNfts = newNumStakedNfts_;

		// Nothing would be broken if this happens to be equal `stakeActionId_`,
		// meaning we are unstaking the stake action that is the last in `stakeActionIds`.
		uint256 lastStakeActionId_ = stakeActionIds[newNumStakedNfts_];

		stakeActions[lastStakeActionId_].index = stakeActionCopy_.index;
		delete stakeActionReference_.index;
		stakeActionIds[stakeActionCopy_.index] = lastStakeActionId_;

		// // [Comment-202502263]
		// // This is unnecessary. Therefore Comment-202502261.
		// // [/Comment-202502263]
		// delete stakeActionIds[newNumStakedNfts_];

		uint256 newActionCounter_ = actionCounter + 1;
		actionCounter = newActionCounter_;
		emit NftUnstaked(newActionCounter_, stakeActionId_, stakeActionCopy_.nftId, msg.sender, newNumStakedNfts_);

		// Comment-202501145 applies.
		randomWalkNft.transferFrom(address(this), msg.sender, stakeActionCopy_.nftId);

		// #endregion
	}

	// #endregion
	// #region `unstakeMany`

	/// @dev
	/// Observable universe entities accessed here:
	///    `unstake`.
	function unstakeMany(uint256[] calldata stakeActionIds_) external override {
		for (uint256 stakeActionIdIndex_ = stakeActionIds_.length; stakeActionIdIndex_ > 0; ) {
			-- stakeActionIdIndex_;
			unstake(stakeActionIds_[stakeActionIdIndex_]);
		}
	}

	// #endregion
	// #region `pickRandomStakerAddressesIfPossible`

	/// @dev
	/// Observable universe entities accessed here:
	///    `RandomNumberHelpers.generateRandomNumber`.
	///    `numStakedNfts`.
	///    `StakeAction`.
	///    `stakeActions`.
	///    `stakeActionIds`.
	function pickRandomStakerAddressesIfPossible(uint256 numStakerAddresses_, uint256 randomNumberSeed_) external view override returns (address[] memory) {
		address[] memory luckyStakerAddresses_;
		uint256 numStakedNftsCopy_ = numStakedNfts;
		if (numStakedNftsCopy_ > 0) {
			luckyStakerAddresses_ = new address[](numStakerAddresses_);
			for (uint256 luckyStakerIndex_ = numStakerAddresses_; luckyStakerIndex_ > 0; ) {
				unchecked { ++ randomNumberSeed_; }
				uint256 randomNumber_ = RandomNumberHelpers.generateRandomNumber(randomNumberSeed_);
				uint256 luckyStakeActionIndex_ = randomNumber_ % numStakedNftsCopy_;
				uint256 luckyStakeActionId_ = stakeActionIds[luckyStakeActionIndex_];
				StakeAction storage luckyStakeActionReference_ = stakeActions[luckyStakeActionId_];
				// #enable_asserts assert(luckyStakeActionReference_.index == luckyStakeActionIndex_);
				address luckyStakerAddress_ = luckyStakeActionReference_.nftOwnerAddress;
				// #enable_asserts assert(luckyStakerAddress_ != address(0));
				-- luckyStakerIndex_;
				luckyStakerAddresses_[luckyStakerIndex_] = luckyStakerAddress_;
			}
		}
		return luckyStakerAddresses_;
	}

	// #endregion
}

// #endregion

